# Check required fields: author, title, year for all entries
python3 - <<'EOF'
import re

bib_path = "/home/ubuntu/.agent-ml-research-idea_gen_0509_16/projects/exec-sim-repair-verifier/docs/paper/references.bib"
with open(bib_path) as f:
    content = f.read()

# Parse entries
entries = re.findall(r'@(\w+)\{(\w+),(.*?)(?=\n@|\Z)', content, re.DOTALL)

for etype, key, body in entries:
    missing = []
    for field in ['author', 'title', 'year']:
        if not re.search(rf'\b{field}\s*=', body, re.IGNORECASE):
            missing.append(field)
    if missing:
        print(f"MISSING FIELDS in {key}: {missing}")
    # Check for journal/booktitle depending on type
    if etype.lower() == 'article':
        if not re.search(r'\bjournal\s*=', body, re.IGNORECASE):
            print(f"MISSING journal in @article {key}")
    elif etype.lower() == 'inproceedings':
        if not re.search(r'\bbooktitle\s*=', body, re.IGNORECASE):
            print(f"MISSING booktitle in @inproceedings {key}")
    elif etype.lower() == 'book':
        if not re.search(r'\bpublisher\s*=', body, re.IGNORECASE):
            print(f"MISSING publisher in @book {key}")

print("Done field check.")
EOF
